import{_ as e,c as d,o as a,ag as r}from"./chunks/framework.DWdSXOaE.js";const y=JSON.parse('{"title":"Colors","description":"","frontmatter":{},"headers":[],"relativePath":"design-standards/colors.md","filePath":"design-standards/colors.md"}'),l={name:"design-standards/colors.md"};function o(s,t,i,n,c,g){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="colors" tabindex="-1">Colors <a class="header-anchor" href="#colors" aria-label="Permalink to &quot;Colors&quot;">​</a></h1><p>The Fluxive Blueprint Theme uses a curated palette of cool grays for the foundation and electric blues for accents.</p><h2 id="primary-palette" tabindex="-1">Primary Palette <a class="header-anchor" href="#primary-palette" aria-label="Permalink to &quot;Primary Palette&quot;">​</a></h2><p>The primary brand color is a vibrant electric blue, used for primary actions, links, and focus states.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Token</th><th style="text-align:left;">Hex</th><th style="text-align:left;">Usage</th></tr></thead><tbody><tr><td style="text-align:left;"><code>blue-600</code></td><td style="text-align:left;"><code>#2563eb</code></td><td style="text-align:left;"><strong>Primary Brand Color</strong>. Used for buttons, active states, and key highlights.</td></tr><tr><td style="text-align:left;"><code>blue-500</code></td><td style="text-align:left;"><code>#3b82f6</code></td><td style="text-align:left;">Secondary accent, hover states for primary buttons.</td></tr><tr><td style="text-align:left;"><code>blue-400</code></td><td style="text-align:left;"><code>#60a5fa</code></td><td style="text-align:left;">Lighter accent, used for subtle emphasis or dark mode highlights.</td></tr></tbody></table><div style="display:flex;gap:1rem;margin:1rem 0;"><div style="background-color:#2563eb;width:100px;height:100px;border-radius:8px;display:grid;place-items:center;font-size:0.8rem;">blue-600</div><div style="background-color:#3b82f6;width:100px;height:100px;border-radius:8px;display:grid;place-items:center;font-size:0.8rem;">blue-500</div><div style="background-color:#60a5fa;width:100px;height:100px;border-radius:8px;display:grid;place-items:center;font-size:0.8rem;color:#111827;">blue-400</div></div><h2 id="neutral-palette-dark-mode" tabindex="-1">Neutral Palette (Dark Mode) <a class="header-anchor" href="#neutral-palette-dark-mode" aria-label="Permalink to &quot;Neutral Palette (Dark Mode)&quot;">​</a></h2><p>We avoid pure black (<code>#000000</code>). Instead, we use rich, deep grays with a slight cool tint to reduce eye strain and provide a premium feel.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Token</th><th style="text-align:left;">Hex</th><th style="text-align:left;">Usage</th></tr></thead><tbody><tr><td style="text-align:left;"><code>gray-900</code></td><td style="text-align:left;"><code>#111827</code></td><td style="text-align:left;"><strong>App Background</strong>. The deepest layer of the interface.</td></tr><tr><td style="text-align:left;"><code>gray-800</code></td><td style="text-align:left;"><code>#1f2937</code></td><td style="text-align:left;"><strong>Surface / Card Background</strong>. Used for sidebars, cards, and elevated areas.</td></tr><tr><td style="text-align:left;"><code>gray-700</code></td><td style="text-align:left;"><code>#374151</code></td><td style="text-align:left;">Borders, dividers, and secondary surface elements.</td></tr><tr><td style="text-align:left;"><code>gray-500</code></td><td style="text-align:left;"><code>#6b7280</code></td><td style="text-align:left;">Muted text, metadata, and icons.</td></tr><tr><td style="text-align:left;"><code>gray-300</code></td><td style="text-align:left;"><code>#d1d5db</code></td><td style="text-align:left;"><strong>Secondary Text</strong>. Body text in some contexts.</td></tr></tbody></table><div style="display:flex;gap:1rem;margin:1rem 0;"><div style="background-color:#111827;width:100px;height:100px;border-radius:8px;display:grid;place-items:center;font-size:0.8rem;border:1px solid #374151;">gray-900</div><div style="background-color:#1f2937;width:100px;height:100px;border-radius:8px;display:grid;place-items:center;font-size:0.8rem;border:1px solid #374151;">gray-800</div><div style="background-color:#374151;width:100px;height:100px;border-radius:8px;display:grid;place-items:center;font-size:0.8rem;">gray-700</div></div><h2 id="text-colors" tabindex="-1">Text Colors <a class="header-anchor" href="#text-colors" aria-label="Permalink to &quot;Text Colors&quot;">​</a></h2><p>High contrast is essential for readability, but we soften it slightly to match the dark theme.</p><ul><li><strong>Primary Text</strong>: <code>#f9fafb</code> (Near White) - Used for headings and main body content.</li><li><strong>Secondary Text</strong>: <code>#d1d5db</code> (Light Gray) - Used for descriptions and supporting text.</li><li><strong>Muted Text</strong>: <code>#9ca3af</code> (Medium Gray) - Used for placeholders and disabled states.</li></ul>',13)])])}const f=e(l,[["render",o]]);export{y as __pageData,f as default};
